package com.srenterprises.controller;
import com.srenterprises.entity.*; import com.srenterprises.repository.*; import jakarta.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController { final ProductRepository products; final CategoryRepository categories; final InventoryRepository inventories; ProductController(ProductRepository p,CategoryRepository c,InventoryRepository i){products=p;categories=c;inventories=i;} record Input(@NotBlank String name,@NotBlank String sku,@NotNull BigDecimal price,String description,UUID categoryId,Integer stock,Boolean featured){} record View(UUID id,String name,String slug,String sku,BigDecimal price,String description,String status,Integer stock,String category){} View view(Product p){var i=inventories.findByProductId(p.id).orElse(null);return new View(p.id,p.name,p.slug,p.sku,p.discountPrice!=null?p.discountPrice:p.price,p.description,p.status.name(),i==null?0:i.quantity,p.category==null?null:p.category.name);} @GetMapping public Page<View> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int size){return products.findByStatus(ProductStatus.ACTIVE,PageRequest.of(page,Math.min(size,50),Sort.by("createdAt").descending())).map(this::view);} @GetMapping("/{slug}") public View one(@PathVariable String slug){return view(products.findBySlug(slug).orElseThrow(()->new NoSuchElementException("Product not found")));} @PostMapping @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')") ResponseEntity<View> create(@RequestBody Input x){Product p=new Product();p.name=x.name();p.slug=slug(x.name());p.sku=x.sku();p.price=x.price();p.description=x.description();p.status=ProductStatus.ACTIVE;p.featured=Boolean.TRUE.equals(x.featured());p.category=x.categoryId()==null?null:categories.findById(x.categoryId()).orElseThrow();products.save(p);Inventory i=new Inventory();i.product=p;i.quantity=x.stock()==null?0:x.stock();inventories.save(i);return ResponseEntity.status(201).body(view(p));} String slug(String s){return s.toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");} }
